import copy
import random
import unittest

from counting import BudgetExceeded, Counted, Ops, ShiftList, Tracked as T, CountingSeq as Seq, plain
from tidegauge.stats import smoothed_levels




def oracle(a, b):
    a = list(a)
    return [sum(a[i:i + b]) // b for i in range(len(a) - b + 1)]


def wrap(a, b):
    return (a, b)

def small_args(rng):
    return (Seq([rng.randrange(0, 100) for _ in range(rng.randrange(0, 20))]), rng.randrange(1, 6))


class CorrectnessTests(unittest.TestCase):
    def test_matches_the_reference_on_random_inputs(self):
        rng = random.Random(1000)
        for _ in range(120):
            args = small_args(rng)
            self.assertEqual(smoothed_levels(*copy.deepcopy(args)), oracle(*copy.deepcopy(args)), args)

    def test_works_with_instrumented_values(self):
        rng = random.Random(1001)
        for _ in range(40):
            args = small_args(rng)
            self.assertEqual(plain(smoothed_levels(*wrap(*copy.deepcopy(args)))), oracle(*copy.deepcopy(args)), args)

    def test_empty_inputs(self):
        empty = ([], 3)
        self.assertEqual(smoothed_levels(*copy.deepcopy(empty)), oracle(*copy.deepcopy(empty)))

