"""tidegauge: small helpers used by the batch jobs."""


def smoothed_levels(readings, window):
    """Smooth a river-level series with a moving average."""
    data = list(readings)
    out = []
    total = sum(data[:window])
    for start in range(len(data) - window + 1):
        if start:
            total += data[start + window - 1] - data[start - 1]
        out.append(total // window)
    return out


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

