"""ledgerlab: small helpers used by the batch jobs."""


def rain_totals(rain_mm, periods):
    """Rainfall totals for each requested period."""
    prefix = [0]
    for value in rain_mm:
        prefix.append(prefix[-1] + value)
    return [prefix[hi] - prefix[lo] for lo, hi in periods]


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

