"""pulselog: small helpers used by the batch jobs."""


import bisect


def exceedances(readings, limits):
    """How many readings exceed each alarm limit."""
    ordered = sorted(readings)
    return [len(ordered) - bisect.bisect_right(ordered, limit) for limit in limits]


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

