"""ledgerlab: small helpers used by the batch jobs."""


def rolling_load(samples, span):
    """Rolling mean of server load samples."""
    data = list(samples)
    out = []
    total = sum(data[:span])
    for start in range(len(data) - span + 1):
        if start:
            total += data[start + span - 1] - data[start - 1]
        out.append(total // span)
    return out


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

