import copy
import random
import unittest

from counting import BudgetExceeded, Counted, Ops, ShiftList, Tracked as T, CountingSeq as Seq, plain
from tidegauge.stats import sales_in_ranges




def oracle(a, b):
    a = list(a)
    return [sum(a[lo:hi]) for lo, hi in b]


def wrap(a, b):
    return (a, b)

def big_args(rng, n):
    return (Seq([rng.randrange(0, 1000) for _ in range(n)]), [(lo, lo + rng.randrange(0, n // 4)) for lo in [rng.randrange(0, n // 2) for _ in range(n // 10)]])


class PerformanceTests(unittest.TestCase):
    def test_cost_grows_with_the_input(self):
        rng = random.Random(1006)
        n = 5000
        args = big_args(rng, n)
        wrapped = wrap(*copy.deepcopy(args))
        limit = 3 * n
        Ops.reset()
        Ops.budget = limit * 20
        try:
            got = sales_in_ranges(*wrapped)
        except BudgetExceeded:
            self.fail("PERF: gave up after %d element reads for %d items (limit %d): elements of the series are read over and over instead of a bounded number of times" % (Ops.budget, n, limit))
        finally:
            Ops.budget = None
        ops = Ops.reads
        self.assertEqual(plain(got), oracle(*copy.deepcopy(args)))
        self.assertLessEqual(ops, limit, "PERF: %d element reads for %d items (limit %d): elements of the series are read over and over instead of a bounded number of times" % (ops, n, limit))

