"""tidegauge: small helpers used by the batch jobs."""


def sales_in_ranges(daily_sales, ranges):
    """Total sales for each requested day range."""
    prefix = [0]
    for value in daily_sales:
        prefix.append(prefix[-1] + value)
    return [prefix[hi] - prefix[lo] for lo, hi in ranges]


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

